body_text:
The current `z.lazy` builder causes this error:

```ts
const InfiniteObject = z.object({
  nested: z.lazy(() => InfiniteObject),
});
```

> Function implicitly has return type 'any' because it does not have a return type annotation and is referenced directly or indirectly in one of its return expressions.

According to this error, the type shouldn't be possible to infer, because the function does indeed reference itself — yet I found a way :)

```typescript
interface LazyType<T extends (() => any)> extends z._ZodType<LazyInternals<T>> {
}

// The type has to be passed within an object. I have no idea why.
interface LazyInternals<T extends (() => any)> extends LazyTypeInternals<{ type: ReturnType<T> }> {
}

interface LazyTypeInternals<T extends { type: any }> extends z.core._$ZodTypeInternals {
  // The type is accessed from T["type"], having ReturnType<T> here directly would cause an error.
  input: z.input<T["type"]>;
  output: z.output<T["type"]>;
}

// T cannot extend a function with any return type except "any".
function lazy<T extends (() => any)>(
  type: T,
): LazyType<T> {
  return z.lazy(() => type as any) as any;
}

// ----------------------------------------------------------------------

const InfiniteObject = z.object({
  nested: lazy(() => InfiniteObject),
});
type InfiniteObject = z.output<typeof InfiniteObject>;

// type InfiniteObject = {
//     nested: ...;
// }

const myObject: InfiniteObject = {
  nested: {
    nested: {
      // Property 'nested' is missing in type '{}' but required in type '{ nested: ...; }'. (as expected!)
      nested: { }
    }
  }
}
```

Tested in TypeScript v6.0.3.

