Version: Deno 2.6.7-2.7.0

We’ve noticed a very annoying bug in our project: sometimes the workers don’t start properly.
We use workers for build processes, and sometimes not all of them start, for example, out of 20, only 17 or 18.
It’s as if it doesn’t detect anything at all, no matter how much I tried to debug it, the whole thing just gets stuck.
After i've downgraded to 2.6.6 it works again as it should.

Here is a small snippet from our code if that helps:

Build.ts
```ts
const HandleWorkerEvents =
	(finished: (value: unknown) => void, StartedAt: number, WorkerId: number) =>
		(e: { data: { Action: string;[key: string | number]: any } }) => {
			switch (e.data.Action) {
				case "finished": {
					if (_Config.Output.WorkerFinishCompile)
						console.log(
							`${chalk.magentaBright(`>>`)} ${chalk.gray(`Worker`)} ${chalk.magentaBright(WorkerId)} ${chalk.gray(
								`finished in`,
							)} ${chalk.magentaBright(((Date.now() - StartedAt) / 1000).toFixed(2))}${chalk.gray(`s!`)}`,
						);

					finished(e);
					break;
				}

				case "set_file_checksum": {
					const { FilePath, Checksum } = e.data.Data;
					SetFileChecksum(FilePath, Checksum);

					break;
				}

				case "report_dependencies": {
					const { Dependencies, ResourcePath } = e.data.Data;
					for (const [DepFilePath, _] of Object.entries(Dependencies)) {
						if (!DependencyTree[DepFilePath]) DependencyTree[DepFilePath] = {};
						DependencyTree[DepFilePath][ResourcePath] = true;
					}

					break;
				}

				default:
					console.log(chalk.redBright(`>> ${e.data.Action} is not a valid worker action!`));

					break;
			}
		};

export async function BuildResources(ResourcesPaths: string[], ResourcePerWorker?: number) {
	const ShouldRebuild = await DidMiscFilesChange();
	const StartTime = Date.now();

	const RESOURCES_PER_WORKER = Deno.env.get("_RESOURCES_PER_WORKER")
		? Deno.env.get("_RESOURCES_PER_WORKER")
		: 8;

	const USE_WORKERS = Deno.env.get("_USE_WORKERS") === "true";

	if (USE_WORKERS) {
		const CreatedWorkers = Math.ceil(ResourcesPaths.length / (ResourcePerWorker ?? RESOURCES_PER_WORKER));
		const WorkerPromises = [];

		console.log(
			`${chalk.blueBright(">>")} ${chalk.yellow("Currently using env:")} ${chalk.blueBright(EnvPath)}`,
		);

		console.log(
			`${chalk.blueBright(">>")} ${chalk.gray("Building with")} ${chalk.blueBright(CreatedWorkers)} ${chalk.gray(
				"worker thread(s).",
			)}`,
		);

		if (fs.existsSync("./.cache/workers.log"))
			fs.unlinkSync("./.cache/workers.log");

		let i = 1;
		while (ResourcesPaths.length > 0) {
			const ResourcesToCompile = ResourcesPaths.splice(0, RESOURCES_PER_WORKER);
			const WorkerInstance = new Worker(new URL("./Resource.ts", import.meta.url).href, { type: "module" });

			const WorkerStartedAt = Date.now();
			const WorkerInstanceId = i;

			WorkerInstance.postMessage({ Resources: ResourcesToCompile, ShouldRebuild, WorkerInstanceId });
			WorkerPromises.push(
				new Promise((resolve) => {
					WorkerInstance.onmessage = HandleWorkerEvents(resolve, WorkerStartedAt, WorkerInstanceId);
				}),
			);

			i += 1;
		}

		await Promise.all(WorkerPromises);
	} else {
		const BuildPromises = [];
		for (const Manifest of ResourcesPaths) BuildPromises.push(Resource.Create(Manifest).Build());
		await Promise.all(BuildPromises);
	}

	if (_Config.Output.BuildFinished) {
		console.log(" ");
		console.log(
			`${chalk.blueBright(">>")} ${chalk.gray("Build took")} ${chalk.blueBright(
				((Date.now() - StartTime) / 1000).toFixed(2),
			)}${chalk.gray("s!")}`,
		);
		console.log(" ");

		const currentLocale = Deno.env.get("DEFAULT_LOCALE") || "hu_HU";
		const localeFilePath = `./locales/${currentLocale}.po`;
		if (fs.existsSync(localeFilePath))
			SetFileChecksum(localeFilePath);
	}
}
```

Resource.ts:
```ts
self.onmessage = async (e: any) => {
	IS_WORKERS_BEING_USED = true;

	const ResourcePaths = e.data.Resources as string[],
		ShouldRebuild = e.data.ShouldRebuild,
		WorkerInstance = e.data.WorkerInstanceId || 0;

	try {
		debugLog(WorkerInstance, "WORKER", "STARTED", `Processing ${ResourcePaths.length} resources.`);

		for (const Path of ResourcePaths) {
			const ResourceInstance = Resource.Create(Path);

			ResourceInstance.WorkerId = WorkerInstance;
			await ResourceInstance.Build(ShouldRebuild);

			const Dependencies = ResourceInstance._Dependencies;
			if (Object.keys(Dependencies).length > 0)
				self.postMessage({ Action: "report_dependencies", Data: { ResourcePath: Path, Dependencies } });
		}
	} catch (error) {
		debugLog(WorkerInstance, "WORKER", "ERROR", String(error));
		self.postMessage({ Action: "error", Error: String(error) });
	}

	debugLog(WorkerInstance, "WORKER", "FINISHED", `All resources processed.`);
	self.postMessage({ Action: "finished" });
	self.close();
};
```

