<summary><code>raw-client.ts</code></summary>

```ts
// Raw HTTP/1.1 client helpers over node:net. Works on Bun, Deno and Node.
import * as net from "node:net"

export interface Outcome {
  readonly raw: string
  readonly statusLine: string
  readonly headers: Record<string, Array<string>>
  readonly body: string
  readonly end: "fin" | "error" | "timeout" | "open"
  readonly errorCode?: string
}

export const connect = (port: number): Promise<net.Socket> =>
  new Promise((resolve, reject) => {
    const socket = net.connect({ host: "127.0.0.1", port })
    socket.setNoDelay(true)
    socket.once("connect", () => resolve(socket))
    socket.once("error", reject)
  })

const parseHead = (raw: string) => {
  const idx = raw.indexOf("\r\n\r\n")
  const head = idx === -1 ? raw : raw.slice(0, idx)
  const body = idx === -1 ? "" : raw.slice(idx + 4)
  const [statusLine, ...lines] = head.split("\r\n")
  const headers: Record<string, Array<string>> = {}
  for (const line of lines) {
    const i = line.indexOf(":")
    if (i === -1) continue
    const name = line.slice(0, i).trim().toLowerCase()
    const value = line.slice(i + 1).trim()
    ;(headers[name] ??= []).push(value)
  }
  return { statusLine: statusLine ?? "", headers, body }
}

/** Collects everything the server sends until FIN, error or timeout. */
export const collect = (socket: net.Socket, timeoutMs: number): Promise<Outcome> =>
  new Promise((resolve) => {
    const chunks: Array<Buffer> = []
    let done = false
    const finish = (end: Outcome["end"], errorCode?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      const raw = Buffer.concat(chunks).toString("latin1")
      resolve({ raw, ...parseHead(raw), end, errorCode })
    }
    const timer = setTimeout(() => finish("timeout"), timeoutMs)
    socket.on("data", (d) => chunks.push(d))
    socket.once("end", () => finish("fin"))
    socket.once("error", (e: NodeJS.ErrnoException) => finish("error", e.code))
    socket.once("close", () => finish(socket.errored ? "error" : "fin"))
  })

/** Waits for one complete response head (and a Content-Length body) without consuming FIN. */
export const readResponse = (socket: net.Socket, timeoutMs: number): Promise<Outcome> =>
  new Promise((resolve) => {
    let raw = ""
    let done = false
    const finish = (end: Outcome["end"], errorCode?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      socket.off("data", onData)
      resolve({ raw, ...parseHead(raw), end, errorCode })
    }
    const timer = setTimeout(() => finish("timeout"), timeoutMs)
    const onData = (d: Buffer) => {
      raw += d.toString("latin1")
      const idx = raw.indexOf("\r\n\r\n")
      if (idx === -1) return
      const { headers } = parseHead(raw)
      const len = Number(headers["content-length"]?.[0] ?? "0")
      if (raw.length - idx - 4 >= len) finish("open")
    }
    socket.on("data", onData)
    socket.once("end", () => finish("fin"))
    socket.once("error", (e: NodeJS.ErrnoException) => finish("error", e.code))
  })

/**
 * Writes `total` bytes in `chunk`-sized pieces, counting the bytes the kernel
 * accepted (write callback fired). Stops at the first error, FIN or timeout.
 */
export const pump = (socket: net.Socket, total: number, chunk: number, timeoutMs: number): Promise<{
  readonly flushed: number
  readonly end: "complete" | "error" | "fin" | "timeout"
  readonly errorCode?: string
  readonly ms: number
}> =>
  new Promise((resolve) => {
    const started = Date.now()
    const buf = Buffer.alloc(chunk, 0x61)
    let flushed = 0
    let sent = 0
    let done = false
    const finish = (end: "complete" | "error" | "fin" | "timeout", errorCode?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      resolve({ flushed, end, errorCode, ms: Date.now() - started })
    }
    const timer = setTimeout(() => finish("timeout"), timeoutMs)
    socket.once("error", (e: NodeJS.ErrnoException) => finish("error", e.code))
    socket.once("end", () => finish("fin"))
    socket.once("close", () => finish(socket.errored ? "error" : "fin"))
    const next = () => {
      if (done) return
      if (sent >= total) return finish("complete")
      const n = Math.min(chunk, total - sent)
      sent += n
      const ok = socket.write(n === chunk ? buf : buf.subarray(0, n), () => {
        flushed += n
      })
      if (ok) queueMicrotask(next)
      else socket.once("drain", next)
    }
    next()
  })

export const mib = (n: number) => `${(n / 1024 / 1024).toFixed(2)} MiB`
```

