    const socket = net.connect({ host: "127.0.0.1", port })
    socket.setNoDelay(true)
    socket.once("connect", () => resolve(socket))
    socket.once("error", reject)
  })

const parseHead = (raw: string) => {
  const idx = raw.indexOf("\r\n\r\n")
  const head = idx === -1 ? raw : raw.slice(0, idx)
  const body = idx === -1 ? "" : raw.slice(idx + 4)
  const [statusLine, ...lines] = head.split("\r\n")
  const headers: Record<string, Array<string>> = {}
  for (const line of lines) {
    const i = line.indexOf(":")
    if (i === -1) continue
    const name = line.slice(0, i).trim().toLowerCase()
    const value = line.slice(i + 1).trim()
    ;(headers[name] ??= []).push(value)
  }
  return { statusLine: statusLine ?? "", headers, body }
}

/** Collects everything the server sends until FIN, error or timeout. */
export const collect = (socket: net.Socket, timeoutMs: number): Promise<Outcome> =>
  new Promise((resolve) => {
    const chunks: Array<Buffer> = []
    let done = false
    const finish = (end: Outcome["end"], errorCode?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      const raw = Buffer.concat(chunks).toString("latin1")
      resolve({ raw, ...parseHead(raw), end, errorCode })
    }
    const timer = setTimeout(() => finish("timeout"), timeoutMs)
    socket.on("data", (d) => chunks.push(d))
    socket.once("end", () => finish("fin"))
    socket.once("error", (e: NodeJS.ErrnoException) => finish("error", e.code))
    socket.once("close", () => finish(socket.errored ? "error" : "fin"))
  })

/** Waits for one complete response head (and a Content-Length body) without consuming FIN. */
export const readResponse = (socket: net.Socket, timeoutMs: number): Promise<Outcome> =>
  new Promise((resolve) => {
    let raw = ""
    let done = false
    const finish = (end: Outcome["end"], errorCode?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      socket.off("data", onData)
      resolve({ raw, ...parseHead(raw), end, errorCode })
    }
    const timer = setTimeout(() => finish("timeout"), timeoutMs)
    const onData = (d: Buffer) => {
      raw += d.toString("latin1")
      const idx = raw.indexOf("\r\n\r\n")
      if (idx === -1) return
      const { headers } = parseHead(raw)
      const len = Number(headers["content-length"]?.[0] ?? "0")
      if (raw.length - idx - 4 >= len) finish("open")
    }
    socket.on("data", onData)
    socket.once("end", () => finish("fin"))
    socket.once("error", (e: NodeJS.ErrnoException) => finish("error", e.code))
  })

/**
 * Writes `total` bytes in `chunk`-sized pieces, counting the bytes the kernel
 * accepted (write callback fired). Stops at the first error, FIN or timeout.
 */
export const pump = (socket: net.Socket, total: number, chunk: number, timeoutMs: number): Promise<{
  readonly flushed: number
  readonly end: "complete" | "error" | "fin" | "timeout"
  readonly errorCode?: string
  readonly ms: number
}> =>
  new Promise((resolve) => {
    const started = Date.now()
    const buf = Buffer.alloc(chunk, 0x61)
    let flushed = 0
    let sent = 0
    let done = false
    const finish = (end: "complete" | "error" | "fin" | "timeout", errorCode?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      resolve({ flushed, end, errorCode, ms: Date.now() - started })
    }
    const timer = setTimeout(() => finish("timeout"), timeoutMs)
    socket.once("error", (e: NodeJS.ErrnoException) => finish("error", e.code))
    socket.once("end", () => finish("fin"))
    socket.once("close", () => finish(socket.errored ? "error" : "fin"))
    const next = () => {
      if (done) return
      if (sent >= total) return finish("complete")
      const n = Math.min(chunk, total - sent)
      sent += n
      const ok = socket.write(n === chunk ? buf : buf.subarray(0, n), () => {
        flushed += n
      })
      if (ok) queueMicrotask(next)
      else socket.once("drain", next)
    }
    next()
  })

export const mib = (n: number) => `${(n / 1024 / 1024).toFixed(2)} MiB`
```

</details>

<details>
<summary><code>unread-body.ts</code></summary>

```ts
// What the server does with the rest of a 64 MiB request body after the
// handler has already responded. Same script for Bun and Deno:
//   bun unread-body.ts
//   deno run --allow-net --allow-env unread-body.ts
import { connect, mib, pump, readResponse } from "./raw-client.ts"

const TOTAL = 64 * 1024 * 1024
const FIRST = 64 * 1024

const handler = async (req: Request): Promise<Response> => {
  const path = new URL(req.url).pathname
  if (path === "/health") return new Response("ok")
  if (path.startsWith("/partial")) {
    const reader = req.body!.getReader()
    await reader.read() // read one chunk, leave the rest
    if (path.endsWith("/cancel")) await reader.cancel()
    else reader.releaseLock()
  }
  const headers: Record<string, string> = new URL(req.url).searchParams.has("close") ? { connection: "close" } : {}
  return new Response("too large", { status: 413, headers })
}

const serve = async (): Promise<{ port: number; stop: () => Promise<void> | void }> => {
  if (typeof Bun !== "undefined") {
    const server = Bun.serve({ port: 0, hostname: "127.0.0.1", development: false, fetch: handler })
    return { port: server.port!, stop: () => server.stop(true) }
  }
  const server = Deno.serve({ port: 0, hostname: "127.0.0.1", onListen() {} }, handler)
  return { port: (server.addr as Deno.NetAddr).port, stop: () => server.shutdown() }
}

const runtime = typeof Bun !== "undefined" ? `Bun ${Bun.version}` : `Deno ${Deno.version.deno}`
const { port, stop } = await serve()
console.log(runtime)

const paths = ["/untouched", "/partial", "/partial/cancel", "/untouched?close", "/partial/cancel?close"]
for (const path of paths) {
  for (const framing of ["content-length", "chunked"] as const) {
    const socket = await connect(port)
    const head = framing === "content-length"
      ? `POST ${path} HTTP/1.1\r\nHost: x\r\nContent-Length: ${TOTAL}\r\n\r\n`
      : `POST ${path} HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\n\r\n${TOTAL.toString(16)}\r\n`
    socket.write(head)
    socket.write(Buffer.alloc(FIRST, 0x61))
    const response = await readResponse(socket, 3000)
    const rest = await pump(socket, TOTAL - FIRST, 1024 * 1024, 5000)
    if (framing === "chunked" && rest.end === "complete") socket.write("\r\n0\r\n\r\n")
    let reuse = "n/a"
    if (rest.end === "complete") {
      socket.write("GET /health HTTP/1.1\r\nHost: x\r\n\r\n")
      const second = await readResponse(socket, 1500)
      reuse = second.end === "open" ? second.statusLine : `${second.end}${second.errorCode ? ` (${second.errorCode})` : ""}`
    }
    console.log(`\n== ${path} (${framing})`)
    console.log(`response: ${response.statusLine} | connection: ${JSON.stringify(response.headers["connection"] ?? null)}`)
    console.log(
      `rest of body: ${mib(rest.flushed + FIRST)} of ${mib(TOTAL)} accepted in ${rest.ms} ms, then ${rest.end}${
        rest.errorCode ? ` (${rest.errorCode})` : ""
      }`
    )
    console.log(`next request on the same connection: ${reuse}`)
    socket.destroy()
  }
}

await stop()
```

