import { connect, readResponse } from "./raw-client.ts"
const server = Deno.serve({ port: 0, hostname: "127.0.0.1", onListen() {} }, async (req) => {
  if (new URL(req.url).pathname === "/cancel") {
    const reader = req.body!.getReader()
    await reader.read()
    await reader.cancel()
  }
  return new Response("too large", { status: 413, headers: { connection: "close" } })
})
const port = (server.addr as Deno.NetAddr).port
for (const path of ["/", "/cancel"]) {
  const socket = await connect(port)
  socket.write(`POST ${path} HTTP/1.1\r\nHost: x\r\nContent-Length: 100\r\n\r\n` + "a".repeat(100))
  const res = await readResponse(socket, 2000)
  console.log(`== ${path}\n${res.raw.split("\r\n\r\n")[0]}`)
  socket.write("GET /health HTTP/1.1\r\nHost: x\r\n\r\n")
  const second = await readResponse(socket, 1500)
  console.log(`next request: ${second.end === "open" ? second.statusLine : second.end}\n`)
  socket.destroy()
}
await server.shutdown()
